# Tiles: v void, f floor, w wall, e enemy spawn, p player spawn, x goal (enemy exit), g grass, m mud, s snow, r rock, ~ water

[properties]
name: Example Area
stories: campaigns/gis/map_01/map_01_story.ron
loot: 1-3 per 40
escape_limit: 10
townsfolk: 16
base: campaigns/gis/world/world.map
region: 78, 78, 80, 80

[markers]
# marker: player | spawn | goal | at: <x, y in the base map's tiles>
marker: goal | at: 118, 118
marker: player | at: 120, 118
marker: spawn | at: 97, 78
marker: spawn | at: 157, 108
marker: spawn | at: 78, 124
marker: spawn | at: 85, 78

[placements]
# at: x, y | def: <def under assets/, e.g. defs/Barrel.ron> | rotation: <degrees, steps of 45>

[waves]
# enemy: <enemy def under assets/, omit for the built-in alien> | count: <n> | rate: <per minute>
count: 8 | rate: 8
enemy: defs/Bunny.ron | count: 12 | rate: 12
count: 20 | rate: 15
